panels.css:
main{padding:0;height:1080px;display:block}
.wrap{position:relative;height:1080px;padding:56px 60px 0;background:radial-gradient(circle at 10% 20%,rgba(214,62,118,.12),transparent 45%),radial-gradient(circle at 92% 80%,rgba(245,197,24,.16),transparent 48%),var(--cream)}
.k{font-size:30px;font-weight:700;color:var(--ink-2);text-align:center}
.t{font-size:66px;font-weight:900;line-height:1.22;text-align:center;margin-top:10px}
.t em{font-style:normal;color:#D63E76}
.note{position:absolute;left:60px;right:60px;bottom:40px;font-size:23px}
.vs{display:flex;gap:24px;margin-top:40px}
.c{flex:1;background:#fff;border-radius:28px;padding:30px 24px;text-align:center;box-shadow:0 20px 40px -26px rgba(30,18,25,.4)}
.c.lo{border-top:14px solid #D63E76}.c.hi{border-top:14px solid #9a8a92}
.c img{height:64px;max-width:300px;object-fit:contain}
.lb{font-size:24px;font-weight:700;color:var(--ink-2);margin-top:10px}
.n{font-size:50px;font-weight:900;margin-top:8px;white-space:nowrap}.n small{font-size:28px}
.c.lo .n{color:#D63E76}
.rows{margin-top:30px;background:#fff;border-radius:24px;padding:10px 30px}
.r{display:flex;align-items:center;padding:16px 0;font-size:28px;border-bottom:2px dashed #eadde3}.r:last-child{border-bottom:0}
.r span{flex:1;font-weight:700}.r b{flex:0 0 280px;color:#D63E76;text-align:right}.r i{flex:0 0 200px;font-style:normal;color:var(--ink-2);text-align:right}

main{padding:0;height:1080px;display:block}
.wrap{position:relative;height:1080px;padding:56px 60px 0;background:radial-gradient(circle at 10% 20%,rgba(214,62,118,.12),transparent 45%),radial-gradient(circle at 92% 80%,rgba(245,197,24,.16),transparent 48%),var(--cream)}
.k{font-size:30px;font-weight:700;color:var(--ink-2);text-align:center}
.t{font-size:66px;font-weight:900;line-height:1.22;text-align:center;margin-top:10px}
.t em{font-style:normal;color:#D63E76}
.note{position:absolute;left:60px;right:60px;bottom:40px;font-size:22px}
.bars{display:flex;flex-direction:column;gap:26px;margin-top:44px;background:#fff;border-radius:28px;padding:34px 34px;box-shadow:0 20px 40px -26px rgba(30,18,25,.4)}
.b{display:grid;grid-template-columns:220px 1fr;grid-template-rows:auto auto;column-gap:22px;row-gap:6px;align-items:center}
.lg img{height:54px;max-width:220px;object-fit:contain}
.bar{height:44px;background:#f3e9ee;border-radius:22px;overflow:hidden;position:relative}
.fill{height:100%;border-radius:22px}.fill.lo{background:#D63E76}.fill.hi{background:#9a8a92}
.v{grid-column:2;font-size:44px;font-weight:900}.v.lo{color:#D63E76}.v small{font-size:24px}
.cap{grid-column:2;font-size:21px;color:var(--ink-2)}
.b{grid-template-rows:auto auto auto}.lg{grid-row:1/4}
.one{text-align:center;font-size:34px;font-weight:700;margin-top:30px}.one b{color:#D63E76;font-weight:900}
.warn{margin-top:20px;text-align:center;font-size:26px;background:#46293A;color:#fff;border-radius:18px;padding:16px 20px}.warn b{color:#F5C518}
